// Sample API service
const API_BASE = 'http://localhost:8080/api'; // adapt as needed

function request(endpoint, method = 'GET', body, token) {
  return fetch(API_BASE + endpoint, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {})
    },
    ...(body ? { body: JSON.stringify(body) } : {})
  }).then(async res => {
    const resp = await res.json();
    if (!res.ok) throw new Error(resp.message || 'Error');
    return resp;
  });
}

const api = {
  login: (credentials) => request('/auth/login', 'POST', credentials),
  register: (data) => request('/auth/register', 'POST', data),
  getUser: (token) => request('/user/me', 'GET', null, token),
  getLeaveRequests: (token) => request('/employee/leaves', 'GET', null, token),
  createLeaveRequest: (data, token) => request('/employee/leaves', 'POST', data, token),
  approveLeave: (leaveId, token) => request(`/manager/leaves/${leaveId}/approve`, 'PUT', null, token),
  rejectLeave: (leaveId, token) => request(`/manager/leaves/${leaveId}/reject`, 'PUT', null, token),
  getNotifications: (token) => request('/notifications', 'GET', null, token),
  // more endpoints as needed
};

export default api;
